export function sum(numbers) {
  if (numbers.length === 0) return 0;

  for (const num of numbers) {
    if (typeof num !== 'number') {
      throw new TypeError('Invalid input');
    }
  }

  return numbers.reduce((acc, num) => acc + num, 0);
}

